package timodern;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
public class InfusionEffectsTest {
    @Test public void originalEffectFees(){assertEquals(32,InfusionEffects.ALL.size());assertEquals(8,InfusionEffects.get("humanus").cost());assertEquals(4,InfusionEffects.get("forbidden_magic:infernus").cost());assertEquals(1,InfusionEffects.get("lux").cost());assertNull(InfusionEffects.get("metallum"));}
    @Test public void schedulesAndImmutability(){assertEquals(200,InfusionEffects.get("gelum").interval());assertEquals(50,InfusionEffects.get("sano").interval());assertEquals(0,InfusionEffects.get("ordo").interval());assertThrows(UnsupportedOperationException.class,()->InfusionEffects.get("iter").hooks().add("incorrect"));}
    @Test public void externalModelDependencies()throws Exception{var root=java.nio.file.Path.of("src/generated/resources");var manifest=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(root.resolve("data/thaumicinfusion/thaumcraft/original_resources.json"))).getAsJsonObject();assertEquals("ae97ab8d1b91e0fb0a66fbef53db03ba0051bdbae2d441227820c45f601ffdb8",manifest.get("sha256").getAsString());try(var files=java.nio.file.Files.walk(root.resolve("assets/thaumicinfusion/models"))){for(var file:files.filter(p->p.toString().endsWith(".json")).toList()){var model=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(file)).getAsJsonObject();if(model.has("textures"))for(var e:model.getAsJsonObject("textures").entrySet()){String texture=e.getValue().getAsString();if(texture.startsWith("thaumicinfusion:"))assertTrue(manifest.getAsJsonObject("mapping").has("assets/"+texture.replace(":","/textures/")+".png"),file+" "+texture);}}}assertTrue(java.nio.file.Files.exists(root.resolve("assets/thaumicinfusion/models/item/focus_infusion_orn.json")));}
}
